<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();$staff=campus_staff();$id=(int)($_GET['id']??0);$error='';$user=current_user();
if(isset($_GET['results'])&&!$staff){http_response_code(403);exit('403 Forbidden');}
if($_SERVER['REQUEST_METHOD']==='POST')try{
    $action=(string)($_POST['action']??'');
    if($action==='create')$id=survey_create($_POST);
    elseif($action==='submit')survey_submit($id,is_array($_POST['answers']??null)?$_POST['answers']:[]);
    elseif($staff&&in_array($action,['publish','close'],true)){
        $from=$action==='publish'?'Draft':'Published';$to=$action==='publish'?'Published':'Closed';
        $query=db()->prepare('UPDATE campus_surveys SET state=? WHERE id=? AND state=?');$query->execute([$to,$id,$from]);
        if(!$query->rowCount())throw new InvalidArgumentException('Survey state changed. Reload this page.');
    }else throw new InvalidArgumentException('Action unavailable.');
    set_flash('success','Survey update saved.');redirect('surveys.php?id='.$id);
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$survey=$id?row('SELECT * FROM campus_surveys WHERE id=?',[$id]):null;
if($id&&(!$survey||(!$staff&&($survey['state']==='Draft'||!survey_eligible($survey,$user))))){http_response_code(404);exit('Survey not found.');}
render_header('School surveys'); ?>
<div class="page-title"><div><h1>School surveys</h1><p>Share feedback to help improve school services.</p></div><a class="btn btn-outline-primary" href="surveys.php">All surveys</a></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if($survey): $questions=json_decode($survey['questions'],true);$done=(bool)scalar('SELECT COUNT(*) FROM campus_survey_participation WHERE survey_id=? AND user_id=?',[$id,$user['id']]); ?>
<section class="panel"><h2><?= e($survey['title']) ?></h2><p class="campus-preserve"><?= e($survey['description']) ?></p><p><?= e($survey['state']) ?> · <?= e($survey['privacy']) ?> · Audience: <?= e($survey['audience']) ?></p>
<?php if($survey['privacy']==='Anonymous'): ?><p>Your identity is not attached to your answers. A separate participation record prevents duplicate submissions. Avoid names and identifying details in free text. Administrators with database or backup access may infer identities; this is not a guarantee of anonymity.</p><p>Staff can view anonymous results only after closing the survey and receiving at least 3 responses.</p><?php else: ?><p>Your account name and answers will be visible to school administrators.</p><?php endif; ?>
<?php if($staff&&$survey['state']==='Draft'): ?><h3>Question preview</h3><ol><?php foreach($questions as $q): ?><li><?= e($q['label']) ?> (<?= e($q['type']) ?>)<?= $q['options']?': '.e(implode(', ',$q['options'])):'' ?></li><?php endforeach; ?></ol><?php endif; ?>
<?php if($staff&&$survey['state']!=='Closed'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $survey['state']==='Draft'?'publish':'close' ?>"><button class="btn btn-primary"><?= $survey['state']==='Draft'?'Publish survey':'Close survey permanently' ?></button></form><p>Questions, privacy, and audience are fixed at creation. Closed surveys cannot reopen.</p><?php endif; ?>
<?php if($done): ?><p role="status">You have already submitted this survey.</p><?php elseif($survey['state']==='Published'&&survey_eligible($survey,$user)): ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="submit">
<?php foreach($questions as $i=>$q): ?><div><label for="answer-<?= $i ?>"><?= e($q['label']) ?> (required)</label>
<?php if($q['type']==='text'): ?><textarea id="answer-<?= $i ?>" name="answers[<?= $i ?>]" required maxlength="1000" class="form-control"></textarea>
<?php else: ?><select id="answer-<?= $i ?>" name="answers[<?= $i ?>]" required class="form-select"><option value="">Choose an answer</option><?php foreach($q['type']==='rating'?['1','2','3','4','5']:$q['options'] as $option): ?><option value="<?= e($option) ?>"><?= e($option) ?></option><?php endforeach; ?></select><?php if($q['type']==='rating'): ?><small>1 = lowest rating; 5 = highest rating.</small><?php endif; ?><?php endif; ?></div><?php endforeach; ?><button class="btn btn-primary">Submit feedback</button></form><?php endif; ?></section>
<?php if($staff): $count=(int)scalar('SELECT COUNT(*) FROM campus_survey_responses WHERE survey_id=?',[$id]); ?><section class="panel"><h2>Staff results</h2><p><?= $count ?> responses</p>
<?php if($survey['privacy']==='Anonymous'&&($survey['state']!=='Closed'||$count<3)): ?><p>Results are hidden until the survey is closed with at least 3 responses.</p>
<?php else: $responses=rows('SELECT r.answers,u.full_name FROM campus_survey_responses r LEFT JOIN users u ON u.id=r.user_id WHERE r.survey_id=? ORDER BY r.id',[$id]); foreach($questions as $i=>$q): ?><h3><?= e($q['label']) ?></h3><?php if($q['type']==='text'): ?><ul><?php foreach($responses as $response): ?><li class="campus-preserve"><?= e(json_decode($response['answers'],true)[$i]) ?></li><?php endforeach; ?></ul><?php else: $values=array_map(fn($r)=>json_decode($r['answers'],true)[$i],$responses); ?><ul><?php foreach($q['type']==='rating'?['1','2','3','4','5']:$q['options'] as $option): ?><li><?= e($option) ?>: <?= count(array_filter($values,fn($v)=>$v===$option)) ?></li><?php endforeach; ?></ul><?php endif; ?><?php endforeach; ?>
<?php if($survey['privacy']==='Identified'): ?><h3>Identified submissions</h3><?php foreach($responses as $response): ?><article><h4><?= e($response['full_name']) ?></h4><ul><?php foreach(json_decode($response['answers'],true) as $i=>$answer): ?><li><?= e($questions[$i]['label']) ?>: <?= e($answer) ?></li><?php endforeach; ?></ul></article><?php endforeach; ?><?php endif; ?><?php endif; ?></section><?php endif; ?>
<?php else: ?><section class="panel"><h2>Available surveys</h2><?php $visible=0;foreach(rows('SELECT * FROM campus_surveys ORDER BY id DESC') as $s): if(!$staff&&($s['state']==='Draft'||!survey_eligible($s,$user)))continue;$visible++; ?><p><a href="surveys.php?id=<?= (int)$s['id'] ?>"><?= e($s['title']) ?></a> · <?= e($s['state']) ?> · <?= e($s['privacy']) ?></p><?php endforeach;if(!$visible): ?><p>No surveys available for your account.</p><?php endif; ?></section>
<?php if($staff): ?><section class="panel"><h2>Create survey</h2><p>Review carefully before creating. To correct a draft, create a replacement; only publish the correct version. All questions are required.</p><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="create">
<label>Survey title<input class="form-control" name="title" required minlength="3" maxlength="120"></label><label>Description<textarea class="form-control" name="description" maxlength="1500"></textarea></label>
<div><label for="privacy">Privacy mode</label><select class="form-select" id="privacy" name="privacy"><option>Anonymous</option><option>Identified</option></select></div>
<div><label for="audience">Audience</label><select class="form-select" id="audience" name="audience"><?php foreach(['All','Student','Parent','Teacher','Admin'] as $role): ?><option><?= e($role) ?></option><?php endforeach; ?></select></div>
<div><label for="course">Course (Student / Parent only)</label><select class="form-select" id="course" name="course_id"><option value="0">All courses</option><?php foreach(rows('SELECT id,code FROM courses WHERE is_offered=1 ORDER BY code') as $course): ?><option value="<?= (int)$course['id'] ?>"><?= e($course['code']) ?></option><?php endforeach; ?></select></div>
<div><label for="section">Section (Student / Parent only)</label><select class="form-select" id="section" name="section_id"><option value="0">All sections</option><?php foreach(rows('SELECT id,name FROM sections ORDER BY name') as $section): ?><option value="<?= (int)$section['id'] ?>"><?= e($section['name']) ?></option><?php endforeach; ?></select></div>
<label>Questions<textarea class="form-control" name="questions" required maxlength="15000" rows="6" placeholder="rating|How was the service?&#10;choice|Preferred session?|Morning|Afternoon&#10;text|What can we improve?"></textarea></label><p>One question per line: rating|Question, choice|Question|Option A|Option B, or text|Question. Maximum 15 questions.</p><button class="btn btn-primary">Create draft</button></form></section><?php endif; ?><?php endif; ?>
<?php render_footer(); ?>
